from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline FDTD-2D kernel, closely matching the PolyBench reference
# implementation. Arrays are laid out as [nx, ny] in row-major order,
# and all computations are done in-place.
@proc
def kernel_fdtd_2d(
    tmax: size,
    nx: size,
    ny: size,
    ex: DATA_TYPE[nx, ny] @ DRAM,
    ey: DATA_TYPE[nx, ny] @ DRAM,
    hz: DATA_TYPE[nx, ny] @ DRAM,
    _fict_: DATA_TYPE[tmax] @ DRAM,
):
    # Time-stepping loop (must remain sequential across t).
    for t in seq(0, tmax):
        # Impose boundary condition on ey along the first row.
        for j in seq(0, ny):
            ey[0, j] = _fict_[t]

        # Update ey using hz (y-direction electric field).
        for i in seq(1, nx):
            for j in seq(0, ny):
                ey[i, j] = ey[i, j] - 0.5 * (hz[i, j] - hz[i - 1, j])

        # Update ex using hz (x-direction electric field).
        for i in seq(0, nx):
            for j in seq(1, ny):
                ex[i, j] = ex[i, j] - 0.5 * (hz[i, j] - hz[i, j - 1])

        # Update hz using the newly updated ex and ey (magnetic field).
        for i in seq(0, nx - 1):
            for j in seq(0, ny - 1):
                hz[i, j] = hz[i, j] - 0.7 * (
                    ex[i, j + 1] - ex[i, j]
                    + ey[i + 1, j] - ey[i, j]
                )

# ---------------------------------------------------------------------------
# Scheduling: exploit spatial parallelism in all per-timestep sweeps.
# Each loop we parallelize has no loop-carried dependences; Exo's effect
# analysis validates safety and the backend lowers them to OpenMP
# parallel loops. The outer time loop t stays sequential.
# ---------------------------------------------------------------------------

kernel_fdtd_2d_sched = kernel_fdtd_2d

# Capture cursors in the original procedure; they will be forwarded
# through subsequent transformations.
ey_boundary_j = kernel_fdtd_2d_sched.find_loop("for j in _:_")
ey_i_loop = kernel_fdtd_2d_sched.find_loop("for i in _:_ #0")
ex_i_loop = kernel_fdtd_2d_sched.find_loop("for i in _:_ #1")
hz_i_loop = kernel_fdtd_2d_sched.find_loop("for i in _:_ #2")

# Parallelize the spatial loops. This maps to OpenMP "parallel for"
# on the outer spatial loop in each sweep.
kernel_fdtd_2d_sched = parallelize_loop(kernel_fdtd_2d_sched, ey_boundary_j)
kernel_fdtd_2d_sched = parallelize_loop(kernel_fdtd_2d_sched, ey_i_loop)
kernel_fdtd_2d_sched = parallelize_loop(kernel_fdtd_2d_sched, ex_i_loop)
kernel_fdtd_2d_sched = parallelize_loop(kernel_fdtd_2d_sched, hz_i_loop)

# Simplify the resulting procedure (clean up any minor algebra or
# structural artifacts introduced by the scheduling steps).
kernel_fdtd_2d_sched = simplify(kernel_fdtd_2d_sched)

# Expose the scheduled version under the original public name so that
# the generated C symbol remains `kernel_fdtd_2d`.
kernel_fdtd_2d = kernel_fdtd_2d_sched
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int tmax = TMAX;
  int nx = NX;
  int ny = NY;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(ex,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(ey,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_2D_ARRAY_DECL(hz,DATA_TYPE,NX,NY,nx,ny);
  POLYBENCH_1D_ARRAY_DECL(_fict_,DATA_TYPE,TMAX,tmax);

  /* Initialize array(s). */
  init_array (tmax, nx, ny,
	      POLYBENCH_ARRAY(ex),
	      POLYBENCH_ARRAY(ey),
	      POLYBENCH_ARRAY(hz),
	      POLYBENCH_ARRAY(_fict_));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_fdtd_2d(/*ctxt=*/NULL, tmax, nx, ny,
                 (DATA_TYPE*)POLYBENCH_ARRAY(ex),
                 (DATA_TYPE*)POLYBENCH_ARRAY(ey),
                 (DATA_TYPE*)POLYBENCH_ARRAY(hz),
                 (DATA_TYPE*)POLYBENCH_ARRAY(_fict_));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nx, ny, POLYBENCH_ARRAY(ex),
				    POLYBENCH_ARRAY(ey),
				    POLYBENCH_ARRAY(hz)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(ex);
  POLYBENCH_FREE_ARRAY(ey);
  POLYBENCH_FREE_ARRAY(hz);
  POLYBENCH_FREE_ARRAY(_fict_);

  return 0;
}
