from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline FDTD-2D kernel. Types use the DATA_TYPE placeholder so that
# the generated C matches PolyBench's DATA_TYPE at compile time.
@proc
def kernel_fdtd_2d_base(
    tmax: size,
    nx: size,
    ny: size,
    ex: DATA_TYPE[nx, ny] @ DRAM,
    ey: DATA_TYPE[nx, ny] @ DRAM,
    hz: DATA_TYPE[nx, ny] @ DRAM,
    _fict_: DATA_TYPE[tmax] @ DRAM,
):
    # The stencil uses ex[i, j+1] and ey[i+1, j], so we must have at least
    # two points in each spatial dimension.
    assert nx > 1
    assert ny > 1

    for t in seq(0, tmax):
        # Hoist _fict_[t] out of the inner j-loop so it is loaded once
        # per time step instead of once per grid point along j.
        fict_t: DATA_TYPE
        fict_t = _fict_[t]

        # Boundary condition along i = 0.
        for j in seq(0, ny):
            ey[0, j] = fict_t

        # Update ey: each row i>0 depends only on the previous row of hz
        # at the same time step, so rows are independent.
        for i in seq(1, nx):
            for j in seq(0, ny):
                ey[i, j] = ey[i, j] - 0.5 * (hz[i, j] - hz[i - 1, j])

        # Update ex: each row i depends only on its own row of hz.
        for i in seq(0, nx):
            for j in seq(1, ny):
                ex[i, j] = ex[i, j] - 0.5 * (hz[i, j] - hz[i, j - 1])

        # Update hz: each (i, j) depends only on ex and ey at the same
        # time step and hz[i, j] itself. Different (i, j) are independent.
        for i in seq(0, nx - 1):
            for j in seq(0, ny - 1):
                hz[i, j] = hz[i, j] - 0.7 * (
                    ex[i, j + 1] - ex[i, j]
                    + ey[i + 1, j] - ey[i, j]
                )


# Scheduling / optimization.
# We keep the iteration order (j innermost) to preserve good spatial
# locality in row-major layout, and exploit parallelism across rows (i).
p = kernel_fdtd_2d_base

# Parallelize the main spatial loops over i. Effect analysis in Exo
# verifies that different rows are independent for each of these loops.
p = parallelize_loop(p, p.find_loop("i #0"))  # ey update
p = parallelize_loop(p, p.find_loop("i #1"))  # ex update
p = parallelize_loop(p, p.find_loop("i #2"))  # hz update

# A final simplification pass cleans up any minor algebra or control
# flow artifacts introduced by the scheduling primitives.
p = simplify(p)

# Export the scheduled kernel under the name expected by the C driver.
kernel_fdtd_2d = rename(p, "kernel_fdtd_2d")
